1	import { useState, useRef, useCallback, useEffect } from 'react';
2	import { Sparkles, X } from 'lucide-react';
3	import { usePermissions } from '@/shared/hooks/usePermissions';
4	import { cn } from '@/shared/lib/utils';
5	import { useLocation, useNavigate } from 'react-router-dom';
6	
7	const FAB_HIDDEN_KEY = 'mia_fab_hidden';
8	const FAB_POS_KEY = 'mia_fab_pos';
9	
10	function getHidden(): boolean {
11	  try { return localStorage.getItem(FAB_HIDDEN_KEY) === '1'; } catch { return false; }
12	}
13	function getSavedPos(): { x: number; y: number } | null {
14	  try {
15	    const raw = localStorage.getItem(FAB_POS_KEY);
16	    return raw ? JSON.parse(raw) : null;
17	  } catch { return null; }
18	}
19	
20	/**
21	 * MiaFab — botão flutuante draggable com dismiss.
22	 *
23	 * Comportamento:
24	 * - Clique → NAVEGA pra /mia (página dedicada). Antes abria chat inline.
25	 * - Drag (touch/mouse) → reposiciona livremente, posição persiste em localStorage.
26	 * - Long press (500ms desktop) ou hover → revela botão X de dismiss.
27	 * - Dismiss → esconde permanentemente até `showMiaFab()` ser chamado.
28	 *
29	 * Decisão de UX: usuários estavam usando o chat inline sem necessidade. A MIA
30	 * tem página dedicada (/mia) com UX completa — o FAB vira atalho de navegação,
31	 * mantendo drag e dismiss pra usuários poderem reposicionar/esconder.
32	 */
33	export function MiaFab() {
34	  const { canViewMia } = usePermissions();
35	  const location = useLocation();
36	  const navigate = useNavigate();
37	
38	  const [hidden, setHidden] = useState(getHidden);
39	  const [showClose, setShowClose] = useState(false);
40	
41	  // Drag state
42	  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
43	  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number; moved: boolean } | null>(null);
44	  const fabRef = useRef<HTMLDivElement>(null);
45	  const closeTimeout = useRef<ReturnType<typeof setTimeout>>();
46	
47	  // Reaparece quando showMiaFab() é chamado em outro lugar
48	  useEffect(() => {
49	    const onShow = () => setHidden(false);
50	    window.addEventListener('mia-fab-show', onShow);
51	    return () => window.removeEventListener('mia-fab-show', onShow);
52	  }, []);
53	
54	  // Inicializa posição salva (clamped pro viewport atual)
55	  useEffect(() => {
56	    const saved = getSavedPos();
57	    if (saved) {
58	      const x = Math.min(Math.max(0, saved.x), window.innerWidth - 48);
59	      const y = Math.min(Math.max(0, saved.y), window.innerHeight - 48);
60	      setPos({ x, y });
61	    }
62	  }, []);
63	
64	  const clampPos = useCallback((x: number, y: number) => {
65	    const size = 48;
66	    return {
67	      x: Math.min(Math.max(0, x), window.innerWidth - size),
68	      y: Math.min(Math.max(0, y), window.innerHeight - size),
69	    };
70	  }, []);
71	
72	  const savePos = useCallback((x: number, y: number) => {
73	    try { localStorage.setItem(FAB_POS_KEY, JSON.stringify({ x, y })); } catch { /* noop */ }
74	  }, []);
75	
76	  // Touch handlers (drag em mobile/tablet)
77	  const onTouchStart = useCallback((e: React.TouchEvent) => {
78	    const touch = e.touches[0];
79	    const rect = fabRef.current?.getBoundingClientRect();
80	    if (!rect) return;
81	    dragRef.current = {
82	      startX: touch.clientX,
83	      startY: touch.clientY,
84	      startPosX: rect.left,
85	      startPosY: rect.top,
86	      moved: false,
87	    };
88	  }, []);
89	
90	  const onTouchMove = useCallback((e: React.TouchEvent) => {
91	    if (!dragRef.current) return;
92	    const touch = e.touches[0];
93	    const dx = touch.clientX - dragRef.current.startX;
94	    const dy = touch.clientY - dragRef.current.startY;
95	    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) {
96	      dragRef.current.moved = true;
97	    }
98	    if (dragRef.current.moved) {
99	      e.preventDefault();
100	      const newPos = clampPos(
101	        dragRef.current.startPosX + dx,
102	        dragRef.current.startPosY + dy,
103	      );
104	      setPos(newPos);
105	    }
106	  }, [clampPos]);
107	
108	  const onTouchEnd = useCallback(() => {
109	    if (dragRef.current?.moved && pos) {
110	      savePos(pos.x, pos.y);
111	    }
112	    if (!dragRef.current?.moved) {
113	      // Tap sem drag → navega pra /mia
114	      navigate('/mia');
115	    }
116	    dragRef.current = null;
117	  }, [pos, savePos, navigate]);
118	
119	  // Desktop: long press revela X (dismiss); click navega
120	  const onMouseDown = useCallback(() => {
121	    closeTimeout.current = setTimeout(() => setShowClose(true), 500);
122	  }, []);
123	  const onMouseUp = useCallback(() => {
124	    if (closeTimeout.current) clearTimeout(closeTimeout.current);
125	  }, []);
126	
127	  const handleDismiss = useCallback((e: React.MouseEvent | React.TouchEvent) => {
128	    e.stopPropagation();
129	    e.preventDefault();
130	    setHidden(true);
131	    try { localStorage.setItem(FAB_HIDDEN_KEY, '1'); } catch { /* noop */ }
132	  }, []);
133	
134	  const handleClick = useCallback(() => {
135	    // Se long-press revelou o X, primeiro click só fecha o X
136	    if (showClose) {
137	      setShowClose(false);
138	      return;
139	    }
140	    navigate('/mia');
141	  }, [showClose, navigate]);
142	
143	  if (!canViewMia() || location.pathname === '/mia' || hidden) return null;
144	
145	  const style: React.CSSProperties = pos
146	    ? { position: 'fixed', left: pos.x, top: pos.y, right: 'auto', bottom: 'auto' }
147	    : {};
148	
149	  return (
150	    <div
151	      ref={fabRef}
152	      className={cn(
153	        "z-40 group",
154	        !pos && "fixed bottom-6 right-6"
155	      )}
156	      style={style}
157	      onTouchStart={onTouchStart}
158	      onTouchMove={onTouchMove}
159	      onTouchEnd={onTouchEnd}
160	    >
161	      {/* Botão de dismiss (X) — revelado via long-press ou hover */}
162	      <button
163	        type="button"
164	        onClick={handleDismiss}
165	        onTouchEnd={(e) => { e.stopPropagation(); handleDismiss(e); }}
166	        className={cn(
167	          "absolute -top-1.5 -right-1.5 z-50 h-5 w-5 rounded-full",
168	          "bg-zinc-700/90 text-white flex items-center justify-center",
169	          "shadow-md transition-all duration-200",
170	          "sm:opacity-0 sm:scale-75 sm:group-hover:opacity-100 sm:group-hover:scale-100",
171	          showClose && "!opacity-100 !scale-100"
172	        )}
173	        aria-label="Esconder atalho da MIA"
174	      >
175	        <X className="h-3 w-3" />
176	      </button>
177	
178	      {/* FAB principal */}
179	      <button
180	        type="button"
181	        onClick={handleClick}
182	        onMouseDown={onMouseDown}
183	        onMouseUp={onMouseUp}
184	        onMouseLeave={onMouseUp}
185	        className={cn(
186	          "h-12 w-12 rounded-full shadow-lg flex items-center justify-center",
187	          "bg-gradient-to-br from-emerald-500 to-teal-600 hover:from-emerald-600 hover:to-teal-700",
188	          "transition-all duration-200 hover:scale-105 hover:shadow-xl",
189	          "touch-none select-none"
190	        )}
191	        aria-label="Abrir Mia (página dedicada)"
192	        title="Abrir MIA"
193	      >
194	        <Sparkles className="h-5 w-5 text-white" />
195	      </button>
196	    </div>
197	  );
198	}
199	
200	/** Re-show o FAB após dismiss (chamável em settings) */
201	export function showMiaFab() {
202	  try { localStorage.removeItem(FAB_HIDDEN_KEY); } catch { /* noop */ }
203	  window.dispatchEvent(new Event('mia-fab-show'));
204	}
