109	// ── Resize hook ──────────────────────────────────────────────
110	
111	type ResizeEdge = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw';
112	
113	function useResize(
114	  initialSize: { w: number; h: number },
115	  minSize = { w: 320, h: 250 },
116	  maxSize = { w: 800, h: typeof window !== 'undefined' ? window.innerHeight - 40 : 900 },
117	) {
118	  const [size, setSize] = useState(initialSize);
119	  const resizing = useRef<{ edge: ResizeEdge; startX: number; startY: number; startW: number; startH: number } | null>(null);
120	
121	  const onResizeStart = useCallback((edge: ResizeEdge, e: React.MouseEvent) => {
122	    resizing.current = { edge, startX: e.clientX, startY: e.clientY, startW: size.w, startH: size.h };
123	    e.preventDefault();
124	    e.stopPropagation();
125	  }, [size]);
126	
127	  useEffect(() => {
128	    const onMouseMove = (e: MouseEvent) => {
129	      const r = resizing.current;
130	      if (!r) return;
131	      const dx = e.clientX - r.startX;
132	      const dy = e.clientY - r.startY;
133	      let newW = r.startW;
134	      let newH = r.startH;
135	
136	      if (r.edge.includes('e')) newW = r.startW + dx;
137	      if (r.edge.includes('w')) newW = r.startW - dx;
138	      if (r.edge.includes('s')) newH = r.startH + dy;
139	      if (r.edge.includes('n')) newH = r.startH - dy;
140	
141	      setSize({
142	        w: Math.max(minSize.w, Math.min(maxSize.w, newW)),
143	        h: Math.max(minSize.h, Math.min(maxSize.h, newH)),
144	      });
145	    };
146	    const onMouseUp = () => { resizing.current = null; };
147	    window.addEventListener('mousemove', onMouseMove);
148	    window.addEventListener('mouseup', onMouseUp);
149	    return () => {
150	      window.removeEventListener('mousemove', onMouseMove);
151	      window.removeEventListener('mouseup', onMouseUp);
152	    };
153	  }, [minSize.w, minSize.h, maxSize.w, maxSize.h]);
154	
155	  return { size, setSize, onResizeStart, isResizing: () => resizing.current !== null };
156	}
157	
158	// ── Resize handle component ──────────────────────────────────
159	
160	function ResizeHandle({ edge, onResizeStart }: { edge: ResizeEdge; onResizeStart: (edge: ResizeEdge, e: React.MouseEvent) => void }) {
161	  const cursorMap: Record<ResizeEdge, string> = {
162	    n: 'cursor-n-resize', s: 'cursor-s-resize', e: 'cursor-e-resize', w: 'cursor-w-resize',
163	    ne: 'cursor-ne-resize', nw: 'cursor-nw-resize', se: 'cursor-se-resize', sw: 'cursor-sw-resize',
164	  };
165	  const posMap: Record<ResizeEdge, string> = {
166	    n: 'top-0 left-2 right-2 h-1.5',
167	    s: 'bottom-0 left-2 right-2 h-1.5',
168	    e: 'right-0 top-2 bottom-2 w-1.5',
169	    w: 'left-0 top-2 bottom-2 w-1.5',
170	    ne: 'top-0 right-0 h-3 w-3',
171	    nw: 'top-0 left-0 h-3 w-3',
172	    se: 'bottom-0 right-0 h-3 w-3',
173	    sw: 'bottom-0 left-0 h-3 w-3',
174	  };
175	
176	  return (
177	    <div
178	      className={cn('absolute z-10', cursorMap[edge], posMap[edge])}
179	      onMouseDown={(e) => onResizeStart(edge, e)}
180	    />
181	  );
182	}
